:root {
  --bg: #1e1e2e;
  --surface: #2a2a3c;
  --primary: #7aa2f7;
  --accent: #bb9af7;
  --text: #e0e0e0;
  --card-back: #3b3b55;
  --card-front: #5c5c8a;
  --matched: #9ece6a;
  --focus: #ffcc00;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: 24px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  gap: 12px;
}

h1 {
  font-size: 1.5rem;
  color: var(--primary);
}

.stats {
  display: flex;
  align-items: center;
  gap: 16px;
}

#move-counter {
  font-weight: 600;
  color: var(--accent);
}

.btn {
  background: var(--primary);
  color: var(--bg);
  border: none;
  border-radius: 8px;
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.card {
  aspect-ratio: 1 / 1;
  background: var(--card-back);
  border-radius: 12px;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s, background 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  border: 2px solid transparent;
  user-select: none;
}

.card:hover {
  transform: scale(1.05);
  background: var(--card-front);
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card:active {
  transform: scale(0.95);
}

.card.flipped,
.card.matched {
  background: var(--card-front);
  cursor: default;
}

.card.matched {
  background: var(--matched);
  border-color: var(--matched);
  cursor: default;
}

.card .symbol {
  display: none;
}

.card.flipped .symbol,
.card.matched .symbol {
  display: block;
}

.win-message {
  text-align: center;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--matched);
  min-height: 2rem;
  transition: opacity 0.3s;
}

@media (max-width: 480px) {
  body {
    font-size: 16px;
    padding: 8px;
  }
  .game-container {
    padding: 16px;
    border-radius: 16px;
  }
  .board {
    gap: 8px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

const COLORS = [
  '#f7768e', '#9ece6a', '#e0af68', '#7aa2f7',
  '#bb9af7', '#7dcfff', '#ff9e64', '#73daca'
];

const board = document.getElementById('board');
const moveCounter = document.getElementById('move-counter');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game');

let deck = [];
let flipped = [];
let matched = 0;
let moves = 0;
let lock = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createDeck() {
  const pairs = COLORS.flatMap(c => [{ color: c, id: c }, { color: c, id: c }]);
  return shuffle(pairs);
}

function renderBoard() {
  board.innerHTML = '';
  deck.forEach((card, index) => {
    const el = document.createElement('button');
    el.className = 'card';
    el.setAttribute('type', 'button');
    el.setAttribute('aria-label', 'Hidden card');
    el.setAttribute('data-index', index);
    el.innerHTML = `<span class="symbol" style="color:${card.color}">■</span>`;
    el.addEventListener('click', () => handleCardClick(index));
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleCardClick(index);
      }
    });
    board.appendChild(el);
  });
}

function handleCardClick(index) {
  if (lock) return;
  const el = board.children[index];
  if (el.classList.contains('flipped') || el.classList.contains('matched')) return;
  if (flipped.includes(index)) return;

  el.classList.add('flipped');
  el.setAttribute('aria-label', 'Revealed card');
  flipped.push(index);

  if (flipped.length === 2) {
    moves++;
    moveCounter.textContent = `Moves: ${moves}`;
    lock = true;
    const [i1, i2] = flipped;
    const card1 = deck[i1];
    const card2 = deck[i2];

    if (card1.id === card2.id) {
      setTimeout(() => {
        board.children[i1].classList.add('matched');
        board.children[i2].classList.add('matched');
        board.children[i1].classList.remove('flipped');
        board.children[i2].classList.remove('flipped');
        board.children[i1].setAttribute('aria-label', 'Matched card');
        board.children[i2].setAttribute('aria-label', 'Matched card');
        matched++;
        flipped = [];
        lock = false;
        checkWin();
      }, 500);
    } else {
      setTimeout(() => {
        board.children[i1].classList.remove('flipped');
        board.children[i2].classList.remove('flipped');
        board.children[i1].setAttribute('aria-label', 'Hidden card');
        board.children[i2].setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lock = false;
      }, 800);
    }
  }
}

function checkWin() {
  if (matched === COLORS.length) {
    winMessage.textContent = `🎉 You won in ${moves} moves! 🎉`;
  }
}

function newGame() {
  deck = createDeck();
  flipped = [];
  matched = 0;
  moves = 0;
  lock = false;
  moveCounter.textContent = 'Moves: 0';
  winMessage.textContent = '';
  renderBoard();
}

newGameBtn.addEventListener('click', newGame);

newGame();
